import React from 'react';
import emailjs from '@emailjs/browser';

const AdminNotifier = {
  sendNewSaleNotification: async () => {
    try {
      // 1. Obtener la lista de administradores y super administradores
      const response = await fetch('https://videojuegoshabana.com/api/listar_admin_superadmin/');

      if (!response.ok) {
        throw new Error('Error al obtener la lista de administradores');
      }

      const admins = await response.json();

      // 2. Filtrar solo los que tienen correo electrónico
      const adminsWithEmail = admins.filter(admin => admin.correo);

      if (adminsWithEmail.length === 0) {
        console.log('No hay administradores con correo electrónico registrado');
        return;
      }

      // 3. Configurar EmailJS
      emailjs.init('W_yqO85fndwrvO0wa');

      // 4. Enviar correo a cada administrador
      const emailPromises = adminsWithEmail.map(admin => {
        const templateParams = {
          to_name: admin.nombre,
          to_email: admin.correo,
          message: 'Se ha generado una nueva venta en el sistema. Por favor revise el panel de administración para más detalles.'
        };

        return emailjs.send(
          'service_codv2pm',
          'template_ygodtuc',
          templateParams
        );
      });

      await Promise.all(emailPromises);
      console.log('Notificaciones enviadas a los administradores');
    } catch (error) {
      console.error('Error al enviar notificaciones:', error);
    }
  }
};

export default AdminNotifier;