import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  Box,
  Typography,
  TextField,
  Button,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Grid,
  Divider,
  Alert,
  CircularProgress,
  Snackbar
} from '@mui/material';
import { DatePicker, LocalizationProvider, TimePicker } from '@mui/x-date-pickers';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import axios from 'axios';
import { jwtDecode } from 'jwt-decode';
import { useCart } from '../context/CartContext';
import AdminNotifier from '../components/AdminNotifier';

const CreateSalesPage = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { clearCart } = useCart();
  
  const [currencies, setCurrencies] = useState([]);
  const [deliveryPoints, setDeliveryPoints] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const [processedItems, setProcessedItems] = useState(0);
  
  const [formData, setFormData] = useState({
    deliveryDateTime: new Date(),
    referencePoint: '', // Combina dirección + referencia
    note: '',
    currencyId: '',
    deliveryPointId: '', // Punto de entrega (domicilio en backend)
    clientName: '',
    clientPhone: '',
    managerPrice: ''
  });
  
  const [currentUser, setCurrentUser] = useState(null);
  const [openSnackbar, setOpenSnackbar] = useState(false);
  const [isManager, setIsManager] = useState(false);

  // Obtener los items del carrito
  const cartItems = location.state?.cartItems || [];

  useEffect(() => {
    const token = localStorage.getItem('authToken');
    if (token) {
      try {
        const decoded = jwtDecode(token);
        setCurrentUser(decoded);
        setIsManager(decoded.rol === 'Gestor de Venta');
      } catch (error) {
        console.error('Error decoding token:', error);
        localStorage.removeItem('authToken');
      }
    }

    const fetchData = async () => {
      try {
        const [currenciesResponse, deliveryPointsResponse] = await Promise.all([
          axios.get('https://videojuegoshabana.com/api/listar_moneda/'),
          axios.get('https://videojuegoshabana.com/api/listar_domicilio/')
        ]);
        
        setCurrencies(currenciesResponse.data);
        setDeliveryPoints(deliveryPointsResponse.data);
        setLoading(false);
      } catch (err) {
        setError('Error al cargar los datos. Intente nuevamente.');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    setError(null);
    setProcessedItems(0);

    try {
      const token = localStorage.getItem('authToken');
      const config = token ? {
        headers: { 'Authorization': `Bearer ${token}` }
      } : {};

      // Procesar cada item del carrito
      const requests = cartItems.map((item) => {
        const salesData = {
          moneda_id: formData.currencyId,
          domicilio_id: formData.deliveryPointId,
          horario_deseado_entrega: formData.deliveryDateTime.toISOString(),
          punto_referencia: formData.referencePoint,
          nota: formData.note,
          cantidad: item.quantity
        };

        if (isManager) {
          salesData.gestor_id = currentUser.user_id;
          salesData.precio_gestor = parseFloat(formData.managerPrice) || 0;
          salesData.nombre_cliente = formData.clientName;
          salesData.telefono_cliente = formData.clientPhone;
        } else if (token) {
          salesData.cliente_id = currentUser.user_id;
        } else {
          salesData.nombre_cliente = formData.clientName;
          salesData.telefono_cliente = formData.clientPhone;
        }

        if (item.isVariation) {
          salesData.variacion_id = item.variationId;
        } else {
          salesData.producto_id = item.id;
        }

        return axios.post('https://videojuegoshabana.com/api/crear_venta/', salesData, config)
          .then(() => {
            setProcessedItems(prev => prev + 1);
          });
      });

      await Promise.all(requests);
      
      // Éxito: vaciar carrito y mostrar mensaje
      clearCart();
      setSuccess(true);
      setOpenSnackbar(true);
      
      // Enviar notificación a administradores
      try {
        await AdminNotifier.sendNewSaleNotification();
      } catch (emailError) {
        console.error('Error al enviar notificaciones:', emailError);
        // No romper el flujo si falla el envío de correos
      }
      
      setTimeout(() => {
        navigate('/shop', { state: { success: true } });
      }, 3000);
    } catch (error) {
      console.error('Error:', error);
      setError(error.response?.data?.message || 
              error.message || 
              'Error al procesar la venta. Intente nuevamente.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleCloseSnackbar = () => {
    setOpenSnackbar(false);
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" mt={4}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error">{error}</Alert>
        <Button 
          variant="contained" 
          sx={{ mt: 2 }}
          onClick={() => window.location.reload()}
        >
          Recargar página
        </Button>
      </Box>
    );
  }

  return (
    <div className="min-h-screen bg-orange-50 p-6">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6 border-l-4 border-orange-400">
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-2xl font-bold text-gray-900">
                Finalizar Compra
              </h1>
              <p className="text-gray-600 mt-1">
                Por favor, complete los datos para finalizar la compra.
              </p>
            </div>
            <Button
              onClick={() => navigate('/shop')}
              sx={{
                backgroundColor: '#000000',
                color: '#ffffff',
                borderRadius: '6px',
                textTransform: 'none',
                fontWeight: 500,
                fontSize: '14px',
                padding: '8px 16px',
                '&:hover': {
                  backgroundColor: '#1f2937'
                }
              }}
            >
              + Volver
            </Button>
          </div>
        </div>

        {/* Formulario */}
        <div className="bg-white rounded-lg shadow-sm p-6 border-l-4 border-orange-400">
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Datos del Cliente */}
            {(isManager || !currentUser) && (
              <div className="space-y-4">
                <h3 className="text-lg font-semibold text-gray-800 border-b border-gray-200 pb-2">
                  Datos del Cliente
                </h3>
                <Grid container spacing={2} sx={{ mb: 3 }}>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Nombre Completo"
                      name="clientName"
                      value={formData.clientName}
                      onChange={handleChange}
                      required
                      sx={{
                        borderRadius: '8px',
                        fontSize: '14px',
                        backgroundColor: '#fef7ed',
                        '& fieldset': {
                          borderColor: '#e5e7eb'
                        },
                        '&:hover fieldset': {
                          borderColor: '#fb923c'
                        },
                        '&.Mui-focused fieldset': {
                          borderColor: '#f97316',
                          borderWidth: '2px'
                        }
                      }}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Teléfono"
                      name="clientPhone"
                      value={formData.clientPhone}
                      onChange={handleChange}
                      required
                      type="tel"
                      sx={{
                        borderRadius: '8px',
                        fontSize: '14px',
                        backgroundColor: '#fef7ed',
                        '& fieldset': {
                          borderColor: '#e5e7eb'
                        },
                        '&:hover fieldset': {
                          borderColor: '#fb923c'
                        },
                        '&.Mui-focused fieldset': {
                          borderColor: '#f97316',
                          borderWidth: '2px'
                        }
                      }}
                    />
                  </Grid>
                </Grid>
                {isManager && (
                  <Grid item xs={12} sx={{ mb: 3 }}>
                    <TextField
                      fullWidth
                      label="Precio del Gestor"
                      name="managerPrice"
                      value={formData.managerPrice}
                      onChange={handleChange}
                      required
                      type="number"
                      inputProps={{ step: "0.01" }}
                      helperText="Ingrese el precio acordado con el cliente"
                      sx={{
                        borderRadius: '8px',
                        fontSize: '14px',
                        backgroundColor: '#fef7ed',
                        '& fieldset': {
                          borderColor: '#e5e7eb'
                        },
                        '&:hover fieldset': {
                          borderColor: '#fb923c'
                        },
                        '&.Mui-focused fieldset': {
                          borderColor: '#f97316',
                          borderWidth: '2px'
                        }
                      }}
                    />
                  </Grid>
                )}
                <Divider sx={{ my: 2 }} />
              </div>
            )}

            {/* Datos de la Compra */}
            <div className="space-y-4">
              <h3 className="text-lg font-semibold text-gray-800 border-b border-gray-200 pb-2">
                Datos de la Compra
              </h3>
              <Typography variant="body1" gutterBottom sx={{ mb: 2 }}>
                Estás comprando {cartItems.length} {cartItems.length === 1 ? 'producto' : 'productos'}
              </Typography>

              <FormControl fullWidth sx={{ mb: 3 }} required>
                <InputLabel sx={{ fontSize: '14px', color: '#6b7280' }}>Moneda</InputLabel>
                <Select
                  name="currencyId"
                  value={formData.currencyId}
                  label="Moneda"
                  onChange={handleChange}
                  required
                  sx={{
                    borderRadius: '8px',
                    fontSize: '14px',
                    backgroundColor: '#fef7ed',
                    '& fieldset': {
                      borderColor: '#e5e7eb'
                    },
                    '&:hover fieldset': {
                      borderColor: '#fb923c'
                    },
                    '&.Mui-focused fieldset': {
                      borderColor: '#f97316',
                      borderWidth: '2px'
                    }
                  }}
                >
                  {currencies.map(currency => (
                    <MenuItem key={currency.id} value={currency.id}>
                      {currency.nombre} (Cambio: {currency.cambio})
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>

              {/* Punto de entrega (domicilio) */}
              <FormControl fullWidth sx={{ mb: 3 }} required>
                <InputLabel sx={{ fontSize: '14px', color: '#6b7280' }}>Punto de Entrega</InputLabel>
                <Select
                  name="deliveryPointId"
                  value={formData.deliveryPointId}
                  label="Punto de Entrega"
                  onChange={handleChange}
                  required
                  sx={{
                    borderRadius: '8px',
                    fontSize: '14px',
                    backgroundColor: '#fef7ed',
                    '& fieldset': {
                      borderColor: '#e5e7eb'
                    },
                    '&:hover fieldset': {
                      borderColor: '#fb923c'
                    },
                    '&.Mui-focused fieldset': {
                      borderColor: '#f97316',
                      borderWidth: '2px'
                    }
                  }}
                >
                  {deliveryPoints.map(deliveryPoint => (
                    <MenuItem key={deliveryPoint.id} value={deliveryPoint.id}>
                      {deliveryPoint.ubicacion} - {deliveryPoint.precio}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>

              <LocalizationProvider dateAdapter={AdapterDateFns}>
                <Grid container spacing={2} sx={{ mb: 3 }}>
                  <Grid item xs={12} sm={6}>
                    <DatePicker
                      label="Fecha de entrega"
                      value={formData.deliveryDateTime}
                      onChange={(newValue) => 
                        setFormData(prev => ({ ...prev, deliveryDateTime: newValue }))
                      }
                      minDate={new Date()}
                      renderInput={(params) => (
                        <TextField 
                          {...params} 
                          fullWidth 
                          required 
                          sx={{
                            borderRadius: '8px',
                            fontSize: '14px',
                            backgroundColor: '#fef7ed',
                            '& fieldset': {
                              borderColor: '#e5e7eb'
                            },
                            '&:hover fieldset': {
                              borderColor: '#fb923c'
                            },
                            '&.Mui-focused fieldset': {
                              borderColor: '#f97316',
                              borderWidth: '2px'
                            }
                          }}
                        />
                      )}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TimePicker
                      label="Hora de entrega"
                      value={formData.deliveryDateTime}
                      onChange={(newValue) => 
                        setFormData(prev => ({ ...prev, deliveryDateTime: newValue }))
                      }
                      renderInput={(params) => (
                        <TextField 
                          {...params} 
                          fullWidth 
                          required 
                          sx={{
                            borderRadius: '8px',
                            fontSize: '14px',
                            backgroundColor: '#fef7ed',
                            '& fieldset': {
                              borderColor: '#e5e7eb'
                            },
                            '&:hover fieldset': {
                              borderColor: '#fb923c'
                            },
                            '&.Mui-focused fieldset': {
                              borderColor: '#f97316',
                              borderWidth: '2px'
                            }
                          }}
                        />
                      )}
                    />
                  </Grid>
                </Grid>
              </LocalizationProvider>

              {/* Punto de referencia (dirección + referencia) */}
              <TextField
                fullWidth
                label="Punto de referencia (Dirección exacta y referencias)"
                name="referencePoint"
                value={formData.referencePoint}
                onChange={handleChange}
                required
                multiline
                rows={4}
                sx={{
                  borderRadius: '8px',
                  fontSize: '14px',
                  backgroundColor: '#fef7ed',
                  '& fieldset': {
                    borderColor: '#e5e7eb'
                  },
                  '&:hover fieldset': {
                    borderColor: '#fb923c'
                  },
                  '&.Mui-focused fieldset': {
                    borderColor: '#f97316',
                    borderWidth: '2px'
                  }
                }}
                helperText="Por favor indique la dirección exacta y puntos de referencia para la entrega"
              />

              <TextField
                fullWidth
                label="Notas adicionales (opcional)"
                name="note"
                value={formData.note}
                onChange={handleChange}
                multiline
                rows={4}
                sx={{
                  borderRadius: '8px',
                  fontSize: '14px',
                  backgroundColor: '#fef7ed',
                  '& fieldset': {
                    borderColor: '#e5e7eb'
                  },
                  '&:hover fieldset': {
                    borderColor: '#fb923c'
                  },
                  '&.Mui-focused fieldset': {
                    borderColor: '#f97316',
                    borderWidth: '2px'
                  }
                }}
              />

              <Button
                type="submit"
                variant="contained"
                color="primary"
                size="large"
                fullWidth
                disabled={submitting || success}
                sx={{
                  backgroundColor: '#000000',
                  color: '#ffffff',
                  borderRadius: '6px',
                  textTransform: 'none',
                  fontWeight: 500,
                  fontSize: '14px',
                  padding: '10px 20px',
                  '&:hover': {
                    backgroundColor: '#1f2937'
                  },
                  '&:disabled': {
                    backgroundColor: '#9ca3af',
                    color: '#ffffff'
                  }
                }}
              >
                {submitting ? (
                  <Box display="flex" alignItems="center">
                    <CircularProgress size={24} color="inherit" />
                    <Typography sx={{ ml: 1 }}>
                      Procesando {processedItems}/{cartItems.length}...
                    </Typography>
                  </Box>
                ) : (
                  success ? 'Compra Exitosa!' : 'Confirmar Compra'
                )}
              </Button>

              {submitting && (
                <Box sx={{ mt: 2, textAlign: 'center' }}>
                  <Typography variant="body2" color="text.secondary">
                    Progreso: {processedItems} de {cartItems.length} productos procesados
                  </Typography>
                </Box>
              )}
            </div>
          </form>
        </div>
      </div>

      {/* Notificaciones */}
      <Snackbar
        open={!!error}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity="error" sx={{ width: '100%' }}>
          {error}
        </Alert>
      </Snackbar>

      <Snackbar
        open={success}
        autoHideDuration={3000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity="success" sx={{ width: '100%' }}>
          ¡Compra realizada con éxito! Redirigiendo...
        </Alert>
      </Snackbar>
    </div>
  );
};

export default CreateSalesPage;